'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['serializeRules']);
assert.strictEqual(typeof api.serializeRules, 'function');
assert.strictEqual(api.serializeRules({}), '');

const rules = Object.freeze({
  color: 'red',
  'font-size': '12px',
  background: 'rgb(1, 2, 3)',
  z9: 'a:b=c'
});
assert.strictEqual(
  api.serializeRules(rules),
  'background:rgb(1, 2, 3);color:red;font-size:12px;z9:a:b=c'
);
assert.deepStrictEqual(rules, {
  color: 'red',
  'font-size': '12px',
  background: 'rgb(1, 2, 3)',
  z9: 'a:b=c'
});

const nullPrototypeRules = Object.create(null);
nullPrototypeRules.beta = '2';
nullPrototypeRules.alpha = '1';
assert.strictEqual(api.serializeRules(nullPrototypeRules), 'alpha:1;beta:2');

for (const invalid of [null, undefined, [], 'rules', 1, new Date()]) {
  assert.throws(() => api.serializeRules(invalid), TypeError);
}

for (const invalidRules of [
  { Color: 'red' },
  { '9color': 'red' },
  { 'font_size': '12px' },
  { 'bad:name': 'x' },
  { 'bad;name': 'x' },
  { color: 1 },
  { color: 'red;blue' },
  { color: '{red}' },
  { color: 'red\nblue' },
  { color: 'red\rblue' }
]) {
  assert.throws(() => api.serializeRules(invalidRules), TypeError);
}

const inherited = Object.create({ color: 'red' });
inherited.size = 'large';
assert.throws(() => api.serializeRules(inherited), TypeError);

